package com.badrulamin.University_Management.entity;  import com.fasterxml.jackson.annotation.JsonProperty; import jakarta.persistence.*; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;  import java.math.BigDecimal;  @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Entity @Table(name = "academic_results") public class AcademicResult extends BaseEntity {      @NotNull     @ManyToOne(fetch = FetchType.LAZY)     @JoinColumn(name = "admission_candidate_id", nullable = false)     private AdmissionCandidate admissionCandidate;      @NotBlank     @Column(name = "institution_name", nullable = false)     private String institutionName;      private String degree;      @Column(name = "passing_year")     private Integer passingYear;      private String grade;      @Column(precision = 5, scale = 2)     private BigDecimal percentage;      @JsonProperty("admissionCandidateId")     public void setAdmissionCandidateId(Long id) {         if (id != null) {             this.admissionCandidate = new AdmissionCandidate();             this.admissionCandidate.setId(id);         }     }      @JsonProperty     public Long getAdmissionCandidateId() {         return this.admissionCandidate != null ? this.admissionCandidate.getId() : null;     } }